%[text] # Plot multiple oriented line segments
%[text] `ax = PlotCycle(vUnits,pUnits,vValues,pValues,opts)` creates an oriented piecewise-defined line plot consisting of lines defined by `(V1(i),P1(i))` up through `(Vn(j),Pn(j))`. 
%[text] ### Examples
%[text] ```matlabCodeExample
%[text] PlotCycle("x","y",[1 3],[2 2],3:-0.2:-2,(0:0.1:2.5).^2+2,TitleStr="A Sharp Curve")
%[text] ```
%[text] ![](text:image:2d47)
%[text] ```matlabCodeExample
%[text] PlotCycle("t","y(t)",[-2 3],[2 2],3:-0.2:-2,2-(0:0.1:2.5).^2,[-2 -2],[-4.25 2],...
%[text]     TitleStr="A Closed Region")
%[text] ```
%[text] ![](text:image:4672)
%[text] ```matlabCodeExample
%[text] PlotCycle("t","y(t)",[-2 3],[2 2],3:-0.2:-2,2-(0:0.1:2.5).^2,[-2 -2],[-4.25 2],...
%[text]     TitleStr="A Closed Region",MyArrows=true,FillRegion=false)
%[text] ```
%[text] #### ![](text:image:28a5)
%[text] #### Options include:
%[text] `TitleStr` is a string with a default value of "`P-V plot"`.
%[text] `Axis` is an axis handle with a default value of `gca`.
%[text] `ResetLimits` is a logical value (default value of `true`) that controls whether the x- and y-limits of the axis are reset to include newly added values. 
%[text] `FillRegion` is a logical value (default value of `true`) that controls whether closed regions are filled
%[text] `FillColor` is an RGB or named color (default value of `[0.9 0.9 0.9]`) such as `[0.3 0 0.3]` or `"r"` or `"green"`.
%[text] `SeriesIndex` is a standard `SeriesIndex`
%[text] `LineWidth` is a standard `LineWidth`
%[text] `MyArrows` is logical value (default value of `false`) that controls whether arrows are plotted in the graph (`true`) or annotations on the figure (`false`). 
function ax = PlotCycle(vUnits,pUnits,vValues,pValues,opts)
    % PLOTCYCLE Function to create a P-V plot
    %
    % Input Arguments:
    %     vUnits   - Units for the volume axis
    %     pUnits   - Units for the pressure axis
    %     vValues  - Volume values (repeating)
    %     pValues  - Pressure values (repeating)
    %     opts     - Options for the plot (TitleStr, Axis, ResetLimits, FillRegion, SeriesIndex, LineWidth)
    %
    % Output Arguments:
    %     ax       - Handle to the axes of the plot
arguments
        vUnits (1,1) string
        pUnits (1,1) string
end
arguments(Repeating)
    vValues (1,:) {mustBeReal,mustBeNumeric}
    pValues (1,:) {mustBeReal,mustBeNumeric}
end
arguments
     opts.TitleStr (1,1) string = "P-V plot"
     opts.Axis = gca
     opts.ResetLimits (1,1) logical = true
     opts.FillRegion (1,1) logical = true
     opts.FillColor = [0.9 0.9 0.9]
     opts.SeriesIndex = 1
     opts.LineWidth = 1
     opts.MyArrows (1,1) logical = false
end
ax = opts.Axis;
allVVals = [vValues{:,:}];
allPVals = [pValues{:,:}];
xlabel(vUnits)
ylabel(pUnits)
title(opts.TitleStr,Interpreter="latex")
if opts.ResetLimits
SetLabels(allVVals,"x",true)
SetLabels(allPVals,"y",true)
xlim(GetBounds(allVVals))
ylim(GetBounds(allPVals))
end

pvLinePlot(ax,vValues,pValues,opts.SeriesIndex,opts.LineWidth,opts.MyArrows);
if opts.FillRegion
    cOpts = colororder;
    SelectedColor = cOpts(opts.SeriesIndex,:);
if allVVals(1)==allVVals(end) && allPVals(1)==allPVals(end)
    fill(allVVals,allPVals,opts.FillColor,"EdgeColor",SelectedColor)
end
end
ax.Children = flipud(ax.Children);
end

function pvLinePlot(ax,vValues,pValues,SeriesColor,Width,MyArrows)
arguments
    ax 
    vValues 
    pValues 
    SeriesColor
    Width
    MyArrows
end
% Helper function to plot the lines, add the arrows, fix the colors, and
% identify the starting and ending points of the path
z = reshape([vValues;pValues],1,[]);
ax.NextPlot = "add";
p = plot(ax,z{:},SeriesIndex=SeriesColor,LineWidth=Width);

series1Color = p(1).Color;
for k = 2:numel(p)
p(k).Color = series1Color;
end

if MyArrows
    [axVals,ayVals] = cellfun(@(V,P) LocateArrowOnCurve(V,P),vValues,pValues,'UniformOutput',false);
    cellfun(@(x,y) AddArrow(ax,x,y,Color=series1Color,SeriesIndex=SeriesColor),axVals,ayVals)
    axis equal
else
    [axVals,ayVals] = cellfun(@(V,P) LocateArrow(V,P,ax),vValues,pValues,'UniformOutput',false);
    cellfun(@(x,y) annotation("arrow",x,y,"Color",series1Color),axVals,ayVals)
end

endPts = [vValues{1}(1) pValues{1}(1); vValues{end}(end) pValues{end}(end)];

ax.NextPlot = "add";
scatter(ax,endPts(:,1),endPts(:,2),50,"Filled",MarkerFaceColor=series1Color)

end


